-- V1.6D: CRO Evidence audit + gerichte uitbreiding
UPDATE public.cro_evidence SET evidence_level='MODERATE', principle='In ecommerce-checkouts verhoogt elk extra zichtbaar formulierveld de waargenomen inspanning; Baymard documenteerde flows die van ~16 naar ~8 velden konden door velden samen te voegen en standaardwaarden te gebruiken.', context='Grootschalig kwalitatief usability-onderzoek (Baymard, 150.000+ uur testing) op ecommerce-checkoutflows; geen gecontroleerd A/B-experiment met gepubliceerde lift.', limitations='Checkout/ecommerce-specifiek: de bestudeerde velden (verzending, betaling) zijn transactioneel, geen lead-kwalificatievelden. NIET automatisch overdraagbaar naar B2B-offerteformulieren, waar extra kwalificerende velden leadkwaliteit juist kunnen verhogen. Hoofdmechanisme is velden samenvoegen/verbergen, niet klakkeloos verwijderen.', recommended_application='Alleen voor checkout-achtige flows: velden samenvoegen, slimme defaults, niet twee keer hetzelfde vragen. Voor B2B-leadformulieren: behandel veldreductie als hypothese en meet zowel volume als leadkwaliteit.', metric='form_submission_rate', applies_to=ARRAY['form']::text[], not_applicable_to=ARRAY['b2b_lead_form','quote_request']::text[], audience='b2c', devices='both', funnel_type=ARRAY['ecommerce_checkout']::text[], tags=ARRAY['form friction','checkout']::text[], published_at=NULL WHERE id='54a6fe16-576a-446a-97b8-ac900fcd6cc0';
UPDATE public.cro_evidence SET source_name='Google Ads Help — Quality Score & landing page experience', source_url='https://support.google.com/google-ads/answer/6167118', principle='Google beloont landingspagina-relevantie (consistentie met advertentie en zoekopdracht) via Quality Score / Ad Rank: hogere relevantie geeft betere positie en lagere kosten. De directe conversie-lift van message match is alleen op case-study-niveau aangetoond.', context='Gedocumenteerd platformmechanisme (Google Ads Help). De veelgeciteerde conversie-lift-percentages (o.a. Campaign Monitor-case) komen uit enkele bureau-case studies — niet peer-reviewed, niet onafhankelijk verifieerbaar.', limitations='Quality Score is een kosten/positie-mechanisme, geen bewijs voor post-click conversie-lift. Specifieke lift-percentages uit case studies zijn WEAK. Effectgrootte varieert per markt; niet getest op ZoetBezorgen.', recommended_application='Neem de dominante zoekintentie (keyword/zoekterm/PMax-categorie) letterlijk terug in H1 en subkop voor betaald verkeer. Behandel specifieke lift-beloftes als illustratief, niet als garantie.', metric='cta_rate', applies_to=ARRAY['hero','headline','ads_traffic']::text[], not_applicable_to=ARRAY['organic_traffic']::text[], audience='both', devices='both', funnel_type=ARRAY['lead_gen','quote_request']::text[], tags=ARRAY['hero','ads','message match']::text[] WHERE id='f4c89a47-dbc5-4fc6-9665-75d3e491c63a';
UPDATE public.cro_evidence SET limitations='Voor B2B-desktopverkeer kan meer context boven de fold juist helpen. Mobiele bezoekers scrollen bereidwilliger dan vaak wordt aangenomen; het gaat om prioritering, niet om alles boven de fold proppen.', devices='mobile', funnel_type=ARRAY['lead_gen','quote_request','ecommerce_checkout']::text[] WHERE id='2a266afb-8865-419b-bb46-d77c69769205';
UPDATE public.cro_evidence SET context='Meerdere onafhankelijke bronnen: Google ''The Need for Mobile Speed'' (2016, 10.000+ mobiele domeinen: 53% verlaat pagina >3s), Vodafone gecontroleerde A/B-test (31% LCP-verbetering → +8% sales, +15% lead-to-visit, web.dev case study 2021), Deloitte ''Milliseconds Make Millions'' (2020, multi-merk inclusief lead-generation vertical).', limitations='Effect is afhankelijk van de startsituatie; een al snelle pagina wint minder. Vodafone is n=1 (geen overdraagbare ratio). Google/Deloitte-studies zijn deels gesponsord en correlationeel. De 53%-statistiek is uit 2016; netwerken en verwachtingen zijn veranderd.', recommended_application='Beperk zware visuals boven de fold, houd de hero licht, meet eigen LCP tegen eigen bounce/conversie in plaats van generieke cijfers als doel te stellen.', tags=ARRAY['mobile','media','performance','core web vitals']::text[] WHERE id='506d47d8-b137-4921-abe1-6660994e05b0';
UPDATE public.cro_evidence SET evidence_level='WEAK', source_name='Afgeleid van Hick''s Law (experimentele psychologie) en Baymard button-usability; eerder geciteerde NN/g-URL bestaat niet', source_url='https://www.nngroup.com/videos/hicks-law-long-menus/', principle='Meerdere visueel gelijkwaardige, concurrerende CTA''s maken de keuze zwaarder (beslistijd stijgt met aantal opties — Hick''s Law). Er is echter geen gecontroleerd onderzoek dat aantoont dat één primaire CTA per landingspagina structureel beter converteert.', context='Hick''s Law is robuust in eenvoudige labtaken, maar CHI 2020-onderzoek (Liu et al.) waarschuwt voor overgeneralisatie naar webdesign. Baymard documenteert wél dat onduidelijke primaire knoppen in checkouts echte usability-fouten veroorzaken.', limitations='Geen direct conversie-onderzoek op landingspagina''s. Een visueel ondergeschikte secundaire actie (bijv. brochure) kan aanvullend werken. Behandelen als plausibele richting, niet als wet.', recommended_application='Geef één actie duidelijke visuele prioriteit; maak secundaire acties visueel ondergeschikt. Test bij twijfel lokaal.', tags=ARRAY['cta','choice']::text[], audience='both', devices='both', funnel_type=ARRAY['lead_gen','quote_request','ecommerce_checkout']::text[], not_applicable_to='{}'::text[] WHERE id='b02b25c1-08ac-4bfc-a65b-49740139a502';
UPDATE public.cro_evidence SET source_name='Cialdini — Influence / peer-reviewed sociale-psychologie-onderzoek', source_url='https://journals.sagepub.com/doi/10.1177/0146167299258006', principle='Social proof is een van de meest gerepliceerde beïnvloedingsprincipes in de sociale psychologie: mensen volgen gedrag van vergelijkbaren, vooral onder onzekerheid. De vertaling naar concrete web-elementen (testimonials, logo''s) is een inferentie — effectgrootte op conversie is contextafhankelijk.', context='Principe: STRONG (decennia gerepliceerd onderzoek, o.a. Cialdini et al. 1999, PSPB). Toepassing op landingspagina''s: MODERATE — geen gecontroleerde web-A/B-studies met generaliseerbare lift.', limitations='Alleen effectief met echte, herkenbare proof; vage claims kunnen vertrouwen schaden. In B2B wegen groepsbeslissingen en risicomijding zwaarder dan simpele sociale conformiteit. Specifieke lift-percentages uit blogs zijn ongecontroleerde vendor-cases.', recommended_application='Plaats bestaand, aantoonbaar bewijs (referenties, cases, logo''s) nabij CTA-zones. Valideer de concrete implementatie met eigen A/B-tests.', tags=ARRAY['trust','testimonials','social proof']::text[], audience='both', devices='both', funnel_type=ARRAY['lead_gen','quote_request']::text[] WHERE id='ad168ec0-d073-4e20-9e26-a89a770af7ce';
UPDATE public.cro_evidence SET source_name='Baymard Institute — Cart Abandonment Research', source_url='https://baymard.com/blog/cart-abandonment', principle='In ecommerce is onduidelijkheid over kosten (verzending, extra kosten) een van de meest gerapporteerde afhaakredenen in de checkout. Voor B2B-prijstransparantie (tonen vs. ''vraag offerte'') bestaat géén gecontroleerd onderzoek.', context='Baymard abandonment-onderzoek is B2C-checkout-specifiek. B2B-prijstransparantie wordt alleen ondersteund door marktscans en opinie (WEAK) en indirect door Gartner''s self-serve-bevindingen.', limitations='Niet overdraagbaar naar B2B zonder eigen test. Meer transparantie kan leadvolume verlagen terwijl leadkwaliteit stijgt — beoordeel op omzet, niet op volume.', recommended_application='Toon vanaf-prijzen/minimale afname waar mogelijk; verwacht lager maar beter gekwalificeerd leadvolume en meet downstream op omzet.', audience='b2c', funnel_type=ARRAY['ecommerce_checkout']::text[], not_applicable_to=ARRAY['b2b_lead_form']::text[], tags=ARRAY['products','quality','pricing']::text[] WHERE id='434d6346-421c-4e53-abfd-f4f31412df7d';
UPDATE public.cro_evidence SET evidence_level='MODERATE', source_name='Nielsen Norman Group — Perceived Value in UI / ''Powered By AI'' Is Not a Value Proposition', source_url='https://www.nngroup.com/articles/powered-by-ai-is-not-a-value-proposition/', principle='Een duidelijke, uitkomstgerichte waardepropositie (wat levert het de bezoeker op) verbetert begrip en geloofwaardigheid in usability-onderzoek; vage of technologiegedreven claims (''Powered by AI'') verlagen helderheid en vertrouwen.', context='NN/g usability-onderzoek (kwalitatief, think-aloud) plus NN/g ''Perceived Value'': eerste indrukken van waarde ontstaan snel en sturen bereidheid tijd te investeren.', limitations='Kwalitatief usability-bewijs (begrip/taaksucces), géén gecontroleerd grootschalig conversie-experiment. Geen generaliseerbare lift-% bekend.', recommended_application='Formuleer de belofte concreet (levering, minimum afname, personalisatie) i.p.v. generieke claims; valideer met 5-seconden- of begripstests.', tags=ARRAY['copy','hero','value proposition']::text[], audience='both', devices='both', funnel_type=ARRAY['lead_gen','quote_request']::text[] WHERE id='6a474f41-062d-41a4-b9b7-5f324e229888';

