INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'above_fold_attention', 'Bezoekers besteden disproportioneel veel aandacht boven de fold (~80% van de kijktijd in NN/g eyetracking), maar ze scrollen wél — aandacht is niet binair.', 'Nielsen Norman Group — Scrolling and Attention / The Fold Manifesto', 'https://www.nngroup.com/articles/scrolling-and-attention/', NULL, 'STRONG', 'Eyetracking-onderzoek over veel sites en schermformaten, meermalen herhaald (origineel + update).', 'Meet aandacht/tijd, geen conversie. Ondersteunt géén specifieke hero-hoogte of vaste fold-positie (varieert per apparaat). Mobiele gebruikers scrollen bereidwilliger.', 'Zet kernpropositie en primaire CTA zichtbaar zonder scrollen op het dominante apparaat van je verkeer; ga er niet vanuit dat niemand scrolt.', 'scroll_depth', ARRAY['hero','page_structure']::text[], ARRAY['exact_hero_height']::text[], 'both', 'both', ARRAY['lead_gen','quote_request','ecommerce_checkout']::text[], ARRAY['hero','attention']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'visual_hierarchy_scanning', 'Bezoekers scannen pagina''s in herkenbare patronen (F-patroon, layer-cake, spotted); duidelijke koppen en front-loaded informatie sturen naar het gunstigere layer-cake-scanpatroon.', 'Nielsen Norman Group — Text Scanning Patterns: Eyetracking Evidence', 'https://www.nngroup.com/articles/text-scanning-patterns-eyetracking/', NULL, 'STRONG', '13+ jaar gerepliceerd eyetracking-onderzoek door een onafhankelijk researchinstituut.', 'Het F-patroon is niet universeel en niet voorschrijvend; NN/g waarschuwt expliciet tegen letterlijk ''in F-vorm ontwerpen''. Zegt niets over sectievolgorde.', 'Gebruik duidelijke koppen/subkoppen, front-load het belangrijkste woord, gebruik bullets en chunking.', 'scroll_depth', ARRAY['page_structure','copy']::text[], ARRAY['section_order_prescription']::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['scannability','visual hierarchy']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'scannability', 'De overgrote meerderheid van webgebruikers scant nieuwe pagina''s in plaats van woord-voor-woord te lezen; beknopte, scanbare opmaak werkt beter dan dichte tekstblokken.', 'Nielsen Norman Group — How Users Read on the Web', 'https://www.nngroup.com/articles/how-users-read-on-the-web/', NULL, 'STRONG', 'Origineel NN/g-onderzoek (79% scant, 16% leest woordelijk), later longitudinaal bevestigd: scanpatronen bleven 13 jaar stabiel ondanks nieuwe devices.', 'Het 79%-cijfer is oud en klein-sample; citeer het niet als moderne grootsteekproef-statistiek. Zegt niets over ideale sectielengte of paginalengte.', 'Breek content in korte, goed gelabelde secties met scanbare opmaak; vermijd dichte alinea''s.', 'scroll_depth', ARRAY['copy','page_structure']::text[], ARRAY['section_length_prescription']::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['scannability']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'image_relevance', 'Gebruikers letten op afbeeldingen die relevante informatie dragen (echte mensen in context, productdetails, informatieve diagrammen) maar negeren puur decoratieve stockfotografie grotendeels.', 'Nielsen Norman Group — Photos as Web Content', 'https://www.nngroup.com/articles/photos-as-web-content/', NULL, 'MODERATE', 'NN/g eyetracking- en usability-onderzoek over content- en ecommerce-sites; binnen hun programma meermalen bevestigd.', 'Aandacht (fixatie) is een proxy voor engagement, geen directe conversiemeting. Publieke artikelen geven geen ruwe data/effectgroottes.', 'Vervang generieke stockfoto''s door beeld dat echte product- of taakinformatie draagt; op mobiel extra kritisch (laadtijd + irrelevantie).', 'cta_rate', ARRAY['media','hero','products']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request','ecommerce_checkout']::text[], ARRAY['imagery','visuals']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'banner_blindness', 'Gebruikers negeren systematisch elementen die op advertenties lijken of op advertentieposities staan (''banner blindness'') — inclusief promotionele hero-banners en carrousels.', 'Nielsen Norman Group — Banner Blindness: Original Eyetracking Research', 'https://www.nngroup.com/articles/banner-blindness-original-eyetracking/', NULL, 'STRONG', 'Eyetracking-onderzoek over meer dan een decennium, expliciet herbevestigd in latere studies (ook mobiel).', 'Gaat over advertentie-achtige elementen, niet over alle beeld. Meet aandacht, geen conversie.', 'Vermijd decoratieve hero-banners/carrousels die eruitzien als advertenties als ze belangrijke product- of CTA-informatie dragen.', 'cta_rate', ARRAY['hero','media']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['banner blindness','hero']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'mobile_speed_bounce', 'In een analyse van 10.000+ mobiele domeinen vond Google dat 53% van mobiele bezoeken wordt afgebroken bij laadtijden boven 3 seconden; bouncekans stijgt sterk tussen 1s en 10s.', 'Google — The Need for Mobile Speed (2016)', 'https://blog.google/products/admanager/the-need-for-mobile-speed/', '2016-09-08', 'MODERATE', 'Grootschalige gedragsdata (Google/DoubleClick + AMP Project), cross-referenced door onafhankelijke bronnen.', 'Studie uit 2016: netwerken en verwachtingen zijn veranderd. Publisher/ad-revenue-context. Correlationeel, geen per-site experiment.', 'Behandel ~3 seconden als ruwe geduldsgrens; valideer met eigen LCP-tegen-bounce data in plaats van de 53% als universeel cijfer te gebruiken.', 'bounce_rate', ARRAY['page_structure','media','mobile']::text[], '{}'::text[], 'both', 'mobile', ARRAY['lead_gen','quote_request']::text[], ARRAY['performance','mobile']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'cwv_lcp_business_case', 'Vodafone''s gecontroleerde A/B-test toonde dat 31% LCP-verbetering +8% sales, +15% lead-to-visit en +11% cart-to-visit opleverde; Deloitte''s multi-merk-studie (incl. lead-generation vertical) vond meetbare funnel-progressie per 0,1s snelheidsverbetering.', 'Google web.dev — Vodafone case study / Deloitte ''Milliseconds Make Millions''', 'https://web.dev/case-studies/vodafone', '2021-03-17', 'MODERATE', 'Vodafone: echte productie-A/B-test met business-outcome (2021). Deloitte (2020): multi-merk, multi-industrie velddata met statistische modellering, expliciet inclusief lead-generation merken.', 'Vodafone is n=1: de exacte ratio is niet overdraagbaar. Deloitte is door Google gecommissioneerd (belangenconflict) en correlationeel. Selectiebias in gepubliceerde cases.', 'Gebruik als richtinggevend bewijs dat LCP-verbetering omzet én leadmetrics kan bewegen; niet als formule om eigen lift te voorspellen.', 'revenue', ARRAY['page_structure','performance']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request','ecommerce_checkout']::text[], ARRAY['performance','core web vitals']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'product_images_quality', 'Ecommerce-gebruikers vertrouwen sterk op productbeeld bij beoordeling; onvoldoende resolutie/zoom of te weinig beeld is een terugkerende usability-fout. Academisch onderzoek koppelt fotokwaliteit aan koopintentie via waargenomen diagnosticiteit.', 'Baymard Institute — Image Resolution & Zoom / PACIS 2014 (peer-reviewed)', 'https://baymard.com/blog/ensure-sufficient-image-resolution-and-zoom', NULL, 'MODERATE', 'Baymard grootschalig usability-onderzoek + peer-reviewed IS-onderzoek (Li, Wang et al., PACIS 2014) naar fotokwaliteit en koopintentie.', 'Ecommerce-specifiek; niet gevalideerd voor B2B-leadgen. Academische effectgroottes bescheiden en categoriegebonden. Baymard''s volledige statistiek zit achter betaalmuur.', 'Zorg per product voor minimaal één groot/in-scale beeld met werkende zoom (ook pinch op mobiel); investeer in fotokwaliteit als trust-input.', 'lead_rate', ARRAY['products','media']::text[], ARRAY['b2b_service_pages']::text[], 'b2c', 'both', ARRAY['ecommerce_checkout']::text[], ARRAY['product imagery']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'product_image_types', 'Baymard onderscheidt 7 productbeeldtypen (studio, in-context/lifestyle, in-scale, on-model, diagram, verpakking e.a.) die elk een ander begripsdoel dienen op productpagina''s.', 'Baymard Institute — UX: 7 Types of Product Images', 'https://baymard.com/blog/ux-product-image-categories', NULL, 'WEAK', 'Descriptieve taxonomie uit Baymard''s benchmarking van ecommerce-sites.', 'Beschrijft best-practice-patronen; kwantificeert géén conversie-effect per beeldtype.', 'Gebruik als checklist voor een gevarieerde beeldmix per product, niet als bewijs dat een specifiek type converteert.', 'lead_rate', ARRAY['products','media']::text[], '{}'::text[], 'b2c', 'both', ARRAY['ecommerce_checkout']::text[], ARRAY['product imagery']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'lifestyle_vs_product_imagery', 'KNOWLEDGE GAP: er bestaat geen rigoureus, openbaar onderzoek dat lifestyle-beeld tegen product-only-beeld vergelijkt op conversie. Claims als ''lifestyle verhoogt conversie met X%'' zijn niet herleidbaar naar een verifieerbare primaire bron.', 'Geen primaire bron gevonden (Baymard-taxonomie + enkele vendor-case studies)', NULL, NULL, 'HYPOTHESIS', 'Baymard documenteert dat beide typen bestaan en verschillende doelen dienen, maar rangschikt ze niet. Enige gevonden A/B-case (visual consistency, +13%) is een enkele commerciele bureau-test.', 'Volledig ongetest. Behandel als designhypothese: lifestyle-beeld kan context/aspiratie geven, product-only geeft nauwkeurigheid.', 'Formuleer per pagina een hypothese op basis van doelgroep en product; test lokaal met eigen A/B-test voordat dit richtinggevend wordt.', 'lead_rate', ARRAY['media','hero','products']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request','ecommerce_checkout']::text[], ARRAY['knowledge gap','imagery']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'sticky_cta_mobile', 'KNOWLEDGE GAP: geen NN/g-, Baymard- of academisch onderzoek toont een generaliseerbaar conversie-effect van sticky CTA''s op mobiel. Beschikbare bronnen zijn enkele bureau-case studies met gemengde resultaten.', 'Online Dialogue — 33 A/B-tests sticky CTA (commerciële aggregatie)', 'https://www.onlinedialogue.nl/en/blogs/sticky-cta-guaranteed-conversion-uplift/', NULL, 'HYPOTHESIS', 'Meest geloofwaardige bron is een bureau dat 33 eigen tests aggregeert; de eigen framing (''guaranteed uplift?'') toont gemengde uitkomsten. Geen onafhankelijke replicatie.', 'Kan averechts werken (verduistert content, voelt opdringerig). Niet getest voor B2B-leadgen.', 'Als laag-risico, eenvoudig omkeerbaar patroon lokaal A/B-testen tegen een controlegroep zonder sticky bar.', 'cta_rate', ARRAY['cta','mobile']::text[], '{}'::text[], 'both', 'mobile', ARRAY['lead_gen','quote_request']::text[], ARRAY['knowledge gap','sticky cta','mobile']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'personalization', 'KNOWLEDGE GAP: er is geen rigoureus grootschalig veldexperiment dat aantoont dat gepersonaliseerde/dynamische landingspagina-content structureel beter converteert dan een goed ontworpen generieke pagina — zeker niet voor B2B.', 'Geen adequate primaire bron; academische literatuur is gedateerd (AMCIS 2004) of tangentieel (JBR 2025: chatbots vs. statische pagina''s)', NULL, NULL, 'HYPOTHESIS', 'Practitioner-rapportage (PPC Live) toont dat hyper-gepersonaliseerde PPC-landingspagina''s in echte A/B-tests niet altijd winnen. Peer-reviewed B2B-onderzoek (JBR 2025) gaat over conversationele vs. statische pagina''s, niet over personalisatie per se.', 'Personalisatie kan segmentatie raken zonder conversievoordeel; in B2B kan leadkwaliteit/intentie zwaarder wegen dan pagina-personalisatie.', 'Behandel personalisatie als testbare hypothese per segment; meet downstream leadkwaliteit, niet alleen form-fill rate.', 'lead_rate', ARRAY['targeting','copy','hero']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['knowledge gap','personalization']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'multistep_vs_singlestep_forms', 'KNOWLEDGE GAP: de veelgeciteerde claim dat multi-step formulieren 86% beter converteren is herleid naar een self-reported HubSpot-enquête, geen gecontroleerd experiment. Er bestaat geen onafhankelijke, peer-reviewed vergelijking voor commerciële lead-/offerteformulieren.', 'Practitioner-kritiek (Foundgrove e.a.) — debunk van de 86%-statistiek', 'https://foundgrove.com/blog/multi-step-vs-single-step-forms-b2b-conversion', NULL, 'WEAK', 'Bureau-ervaring suggereert dat multi-step pas boven ~6 velden vaker wint, maar tegelijk waarschuwt de ''Form Chunking Illusion'' dat chunking nieuwe afhaakpunten creëert. Resultaten zijn contextafhankelijk en tegenstrijdig.', 'Geen gecontroleerd onderzoek beschikbaar in beide richtingen. Survey-onderzoek (Matzat 2009) is niet overdraagbaar: enquêtemotivatie ≠ offertemotivatie.', 'Presenteer multi-step nooit als bewezen voordeel. Test per formulierlengte en meet per-stap drop-off plus downstream leadkwaliteit.', 'form_submission_rate', ARRAY['form']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['knowledge gap','form friction']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'progress_indicators', 'Peer-reviewed veldexperiment (web-enquêtes) toont dat voortgangsindicatoren drop-out beïnvloeden, maar dat het type indicator ertoe doet: misleidende voortgang (snel begin, traag einde) kan drop-out juist verhogen.', 'Matzat, Snijders & van der Horst (2009) — Social Psychology (peer-reviewed)', 'https://www.onlineumfragen.com/pic/matzat_progress_indicators.pdf', '2009-01-01', 'MODERATE', 'Gerandomiseerd experiment onder echte web-enquêterespondenten met verschillende indicator-designs.', 'Enquêtecompletie ≠ commerciële lead-conversie (andere motivatiestructuur). Versimpel niet naar ''voortgangsbalk helpt altijd''.', 'Bij multi-step offerteformulieren: test het specifieke indicator-ontwerp (accurate vs. voorgeladen pacing) in plaats van te veronderstellen dat elke balk helpt.', 'form_submission_rate', ARRAY['form']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['form friction','multi-step']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'form_usability_general', 'Algemene formulier-hygiëne — minimaal aantal verplichte velden, enkelvoudige kolom, duidelijke markering verplicht/optioneel, logische veldvolgorde — verbetert taaksucces in usability-onderzoek.', 'Nielsen Norman Group — Website Forms Usability: Top 10 Recommendations', 'https://www.nngroup.com/articles/web-form-design/', NULL, 'MODERATE', 'NN/g''s geaggregeerde usability-testing over veel formuliercontexten (signup, survey, checkout, contact).', 'Generieke richtlijnen zonder effectgroottes; niet gesegmenteerd naar B2B/B2C. Zegt niet hoeveel velden ''te veel'' is voor een specifieke funnel.', 'Gebruik als basis-hygiëne voor elk formulier (labels, markering, layout); bepaal veldaantal via eigen data.', 'form_submission_rate', ARRAY['form','form_fields']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request','ecommerce_checkout']::text[], ARRAY['form friction']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'b2b_lead_qualification', 'KNOWLEDGE GAP: er is geen gecontroleerd onderzoek dat de afweging ''meer kwalificerende velden → betere leadkwaliteit tegen acceptabel volumeverlies'' kwantificeert voor B2B-leadformulieren.', 'NN/g B2B Usability (indirect) — geen directe primaire bron', 'https://www.nngroup.com/articles/b2b-usability/', NULL, 'HYPOTHESIS', 'NN/g''s B2B-onderzoek toont dat B2B-sites structureel minder bruikbaar testen en dat frictiereductie in de researchfase leadgeneratie helpt — maar kwantificeert de veld/kwaliteit-tradeoff niet.', 'Alle numerieke claims in blogs zijn self-reported vendor-cases. Baymard''s veldonderzoek is checkout-specifiek en hier niet overdraagbaar.', 'Behandel als testbare hypothese: valideer met eigen A/B-test op zowel form-completion als downstream SQL-/close-rate, nooit alleen op top-of-funnel conversie.', 'qualified_lead_rate', ARRAY['form','form_fields']::text[], ARRAY['ecommerce_checkout']::text[], 'b2b', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['knowledge gap','lead qualification']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'faq_objection_handling', 'KNOWLEDGE GAP: er is geen primair CRO-onderzoek dat het conversie-effect van FAQ- of bezwaarparagraven kwantificeert. Beschikbaar onderzoek gaat over FAQ-vindbaarheid/contentstrategie, niet over verkoopimpact.', 'NN/g — Strategic Design for FAQs (indirect, contentstrategie)', 'https://www.nngroup.com/reports/strategic-design-faqs/', NULL, 'HYPOTHESIS', 'NN/g''s FAQ-rapport adresseert kennismanagement/support, geen landingspagina-conversie. Bibliotheekwetenschappelijke FAQ-usability-studies staan volledig buiten commerciële context.', 'Plausibel via algemene usability-logica (onbeantwoorde vragen → onzekerheid → afhaken), maar ongemeten.', 'Bouw FAQ-content uit echte salesgesprek-bezwaren (niet gokken); meet FAQ-engagement en test lokaal.', 'lead_rate', ARRAY['objections','copy']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['knowledge gap','faq','objections']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'pricing_transparency_b2b', 'KNOWLEDGE GAP: geen onafhankelijk, gecontroleerd onderzoek naar het causale effect van prijstransparantie vs. ''vraag een offerte'' op conversie, vertrouwen of leadkwaliteit in B2B.', 'Marktscans (Dupple: 1 op 3 softwareleveranciers verbergt prijs) en opinie (G2) — geen gecontroleerde studies', 'https://dupple.com/learn/software-pricing-transparency', NULL, 'HYPOTHESIS', 'Indirect ondersteund door Gartner''s self-serve-bevindingen (B2B-kopers willen zelfstandig research doen), maar dat is voorkeursonderzoek, geen conversie-experiment.', 'G2 heeft commercieel belang bij transparantie-narratief. Transparantie kan volume verlagen en kwaliteit verhogen — alleen op omzet te beoordelen.', 'Test lokaal: vanaf-prijs/range vs. volledig gated CTA; meet leadvolume én leadkwaliteit/close-rate.', 'revenue', ARRAY['products','copy','form']::text[], ARRAY['ecommerce_checkout']::text[], 'b2b', 'both', ARRAY['quote_request','lead_gen']::text[], ARRAY['knowledge gap','pricing']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'b2b_buyer_selfserve', 'B2B-kopers besteden het grootste deel van hun aankooptraject aan zelfstandig research: Gartner rapporteert ~17% van de tijd in gesprek met leveranciers en ~45% aan onafhankelijk onderzoek; 61% prefereert een rep-free ervaring (2025).', 'Gartner — B2B Buying Research / Sales Survey 2025', 'https://www.gartner.com/en/newsroom/press-releases/2025-06-25-gartner-sales-survey-finds-61-percent-of-b2b-buyers-prefer-a-rep-free-buying-experience', '2025-06-25', 'MODERATE', 'Grootschalig, methodologisch gedocumenteerd survey-onderzoek, over meerdere jaren consistent in richting.', 'Self-reported voorkeuren, geen geobserveerd gedrag of experiment. Proprietary methodologie deels achter betaalmuur. Nuance: puur self-serve correleert met méér aankoopspijt — Gartner adviseert een blend van digitaal + mens.', 'Investeer in hoogwaardige self-serve content (prijsinfo, cases, specificaties) zodat prospects zelfstandig kunnen voortschrijden; gebruik dit niet om menselijke touchpoints af te schaffen.', 'qualified_lead_rate', ARRAY['targeting','copy','proof']::text[], ARRAY['low_consideration_b2c']::text[], 'b2b', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['b2b','buying behaviour']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'b2b_site_usability', 'NN/g''s B2B-usability-onderzoek toont dat B2B-sites structureel slechter scoren dan consumentensites en dat betere bruikbaarheid (incl. toegankelijk researchmateriaal) prospects helpt converteren naar leads.', 'Nielsen Norman Group — B2B Usability', 'https://www.nngroup.com/articles/b2b-usability/', NULL, 'MODERATE', 'Kwalitatief usability-testing specifiek op B2B-sites door onafhankelijk researchinstituut.', 'Kwalitatief, geen conversie-experiment; geen effectgroottes.', 'Behandel research-toegankelijkheid (specificaties, cases, prijzen) als kernonderdeel van de B2B-landingspagina.', 'lead_rate', ARRAY['page_structure','copy','proof']::text[], '{}'::text[], 'b2b', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['b2b','usability']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'trust_credibility', 'Stanford''s Web Credibility Research (2.500+ participanten) leidde empirisch af dat verifieerbaarheid, een zichtbare echte organisatie, aantoonbare expertise en bereikbaarheid de waargenomen geloofwaardigheid van websites sturen.', 'Stanford University — Web Credibility Project (Fogg et al.)', 'https://credibility.stanford.edu/guidelines/', NULL, 'MODERATE', 'Grootschalig academisch-adjacent onderzoek naar welke cues geloofwaardigheids-oordelen sturen.', 'Onderzoek is ~20 jaar oud; visuele conventies en basis-vertrouwen zijn veranderd. Niet gesegmenteerd naar B2B/B2C; predateert modern mobiel web.', 'Gebruik als duurzame checklist (verifieerbaarheid, echte organisatie, expertise, contactmogelijkheden), niet als letterlijke visuele voorschriften uit 2002.', 'lead_rate', ARRAY['proof','copy']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['trust','credibility']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'trust_seals_checkout', 'Baymard''s testing toont dat gebruikers slechts delen van een checkoutpagina als ''veilig'' waarnemen — op basis van oppervlakkige cues (slotje, bekende betaallogo''s), ongeacht de technische beveiliging.', 'Baymard Institute — Perceived Security in Checkout / Site Seal Trust', 'https://baymard.com/blog/customers-perceive-only-parts-of-a-checkout-page-as-being-secure', NULL, 'MODERATE', 'Kwalitatief usability-onderzoek op perceived-security cues in ecommerce-checkouts (2010-2016).', 'Gedateerd; specifieke seal-rankings zijn verouderd. Ecommerce-checkout-specifiek: NIET overdraagbaar naar B2B-pagina''s zonder betaalstap — daar werken klantlogo''s, certificeringen en cases.', 'Alleen voor checkout-achtige flows: herkenbare betaal-/security badges nabij de betaalstap. Voor B2B: gebruik logo''s, certificeringen en cases.', 'form_submission_rate', ARRAY['proof','form']::text[], ARRAY['b2b_lead_form','quote_request']::text[], 'b2c', 'both', ARRAY['ecommerce_checkout']::text[], ARRAY['trust','security']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'reviews_ecommerce', 'Baymard''s usability-testing toont dat ecommerce-gebruikers actief reviews zoeken, wantrouwig reageren op pagina''s zonder reviews of met uitsluitend 5-sterren-reviews, en dat echte, gemengde reviews vertrouwen en aankoopzekerheid verhogen.', 'Baymard Institute — Product Page & Reviews UX Research', 'https://baymard.com/research/product-page', NULL, 'MODERATE', 'Kwalitatief usability-onderzoek in ecommerce-productpagina-context.', 'Ecommerce/B2C-specifiek: sterren/aantallen-dynamiek vertaalt niet direct naar B2B-testimonials (cases/logo''s i.p.v. volume-ratings).', 'B2C: toon echte (incl. gemengde) reviews. B2B: gebruik named cases, logo''s en quotes — ander trust-mechanisme.', 'lead_rate', ARRAY['proof','products']::text[], ARRAY['b2b_lead_form']::text[], 'b2c', 'both', ARRAY['ecommerce_checkout']::text[], ARRAY['social proof','reviews']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'hicks_law', 'Hick''s Law: beslistijd stijgt met het aantal en de complexiteit van opties — robuust in eenvoudige labtaken, maar de toepasbaarheid op complexe web-/aankoopbeslissingen is betwist.', 'NN/g — Hick''s Law (video) + Liu et al., CHI 2020 ''How Relevant is Hick''s Law for HCI?'' (peer-reviewed)', 'https://perso.telecom-paristech.fr/rioul/publis/202001liugoririoulbeaudouinlafonguiard.pdf', NULL, 'MODERATE', 'Decennia gerepliceerd in experimentele psychologie voor eenvoudige keuzetaken; CHI 2020-paper waarschuwt expliciet voor overgeneralisatie naar UI/menudesign.', 'Alleen STRONG binnen het smalle experimentele paradigma. Visueel zoeken tussen getoonde (niet-gememoriseerde) opties gedraagt zich anders.', 'Vereenvoudig echt complexe keuzesets via groepering/filtering/defaults; gebruik het niet als argument om willekeurig content te schrappen.', 'cta_rate', ARRAY['page_structure','cta','products']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request','ecommerce_checkout']::text[], ARRAY['choice','cognitive load']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'choice_overload', 'Het populaire ''choice overload''-verhaal (Iyengar''s jam-studie) replicaat niet als algemene wet: meta-analyse van 50 studies (Scheibehenne et al. 2010) vond een gemiddeld effect van vrijwel nul; het effect treedt alleen op onder specifieke condities (zeer grote/complexe sets, onduidelijke voorkeuren).', 'Scheibehenne, Greifeneder & Todd (2010) — Journal of Consumer Research (meta-analyse, peer-reviewed)', 'https://www.scheibehenne.de/ScheibehenneGreifenederTodd2010.pdf', '2010-10-01', 'WEAK', 'Meta-analyse over 50 studies + vervolg-meta-analyse (Chernev et al. 2015) die moderatoren identificeert.', 'Het gemiddelde effect is ~nul; alleen conditioneel aanwezig. Geen universele drempel (''nooit meer dan X opties'') bestaat.', 'Versimpel alleen echt complexe optiesets; behandel ''minder keuzes = meer conversie'' nooit als automatisme.', 'cta_rate', ARRAY['products','page_structure']::text[], '{}'::text[], 'both', 'both', ARRAY['ecommerce_checkout','lead_gen']::text[], ARRAY['choice','cognitive load']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'cta_color_copy', 'KNOWLEDGE GAP: er is geen gecontroleerd, repliceerbaar onderzoek dat aantoont dat een specifieke CTA-kleur, -grootte of -copyformule universeel beter converteert. De beroemde ''rood verslaat groen met 21%'' is een enkele vendor-A/B-test die niet repliceert.', 'Geen primaire bron; folklore gedocumenteerd en weerlegd in meerdere analyses', NULL, NULL, 'HYPOTHESIS', 'Retrospectieve analyses tonen dat context (contrast met de omgeving, niet absolute kleur) plausibel het mechanisme is. Een contrarian case (Search Engine Land) toont dat ''best practices''-pagina''s verliezen van onconventionele varianten.', 'Elke kleur/copy-regel is context- en merkafhankelijk; vereist lokale A/B-testing.', 'Zorg dat de CTA visueel contrasteert met zíjn omgeving en de resulterende actie duidelijk benoemt; test kleur/copy uitsluitend lokaal.', 'cta_rate', ARRAY['cta']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['knowledge gap','cta']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'cta_discoverability', 'Baymard''s grootschalige usability-testing documenteert dat gebruikers primaire actieknoppen in transactionele flows daadwerkelijk niet vinden of verkeerd interpreteren door plaatsing- en labelambiguiteit — een reëel, geobserveerd usability-probleem.', 'Baymard Institute — Button Placement & Primary Button Functionality guidelines', 'https://baymard.com/guidelines/556-place-order-button-placement', NULL, 'MODERATE', 'Kwalitatief usability-onderzoek (grootschalig, checkout-flows): gebruikers falen observeerbaar bij het vinden/begrijpen van de primaire knop.', 'Checkout-specifiek; gaat over vindbaarheid/labeling, niet over kleur of copy. Geen conversie-lift gekwantificeerd.', 'Maak de primaire CTA onmiskenbaar vindbaar en label hem met de resulterende actie (''Vraag offerte aan'', niet ''Verstuur'').', 'cta_rate', ARRAY['cta','form']::text[], '{}'::text[], 'both', 'both', ARRAY['ecommerce_checkout','quote_request','lead_gen']::text[], ARRAY['cta','usability']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'hero_layout_direction', 'KNOWLEDGE GAP: NN/g''s ''Horizontal Attention Leans Left'' toont een algemene links-aandachtsbias (69% links vs. 30% rechts), maar dit is 15+ jaar oud onderzoek op generieke layouts — geen gecontroleerde test van hero-beeld-links-vs-rechts op conversie.', 'Nielsen Norman Group — Horizontal Attention Leans Left (indirect)', 'https://www.nngroup.com/articles/horizontal-attention-original-research/', NULL, 'HYPOTHESIS', 'Aandachtsbias is gemeten, conversie-effect van hero-richting niet.', 'Geen betrouwbaar bewijs voor ''beeld moet rechts/links''. Volledig contextafhankelijk.', 'Kies hero-layout op basis van content en merk; test richting alleen lokaal als het ertoe doet.', 'cta_rate', ARRAY['hero','visual_treatment']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['knowledge gap','hero']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'section_order', 'KNOWLEDGE GAP: er bestaat geen betrouwbaar primair onderzoek dat één universeel optimale sectievolgorde voor landingspagina''s voorschrijft (bijv. hero → proof → features → FAQ → CTA).', 'Geen primaire bron gevonden', NULL, NULL, 'HYPOTHESIS', 'Volgorde is sterk afhankelijk van funneltype, verkeersbron en bewustzijnsfase van de bezoeker. Copywriting-frameworks (bijv. Schwartz'' awareness-stages) zijn heuristieken, geen empirisch gevalideerde studies.', 'Geen pseudo-wetenschap: registreer als gap en laat de Strategist vanuit intentie/context een hypothese vormen.', 'Bepaal sectievolgorde als expliciete hypothese vanuit zoekintentie en context; leer via eigen data en A/B-tests.', 'lead_rate', ARRAY['section_order','page_structure']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['knowledge gap','section order']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'section_count_page_length', 'KNOWLEDGE GAP: geen kwantitatief onderzoek koppelt een specifiek aantal secties of paginalengte aan conversie-uitkomsten.', 'Geen primaire bron gevonden', NULL, NULL, 'HYPOTHESIS', 'Scanbaarheidsonderzoek (NN/g) ondersteunt korte, goed gelabelde secties, maar zegt niets over hoeveel secties of hoe lang een pagina mag zijn.', 'Volledig contextafhankelijk (aanbod, intentie, prijspunt).', 'Laat paginalengte volgen uit de benodigde bezwaarafhandeling en bewijslast, niet uit een vaste regel.', 'lead_rate', ARRAY['page_structure']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['knowledge gap','page length']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'background_color_contrast', 'KNOWLEDGE GAP: buiten WCAG-toegankelijkheidsminima (die over leesbaarheid gaan, niet over conversie) bestaat geen betrouwbaar onderzoek dat specifieke achtergrondkleuren of paletten aan conversie koppelt.', 'Geen primaire bron gevonden (WCAG = toegankelijkheidsstandaard, geen CRO-onderzoek)', NULL, NULL, 'HYPOTHESIS', 'Kleurpsychologie-claims in marketingblogs zijn ongecontroleerd en niet repliceerbaar.', 'Merk- en contextafhankelijk.', 'Volg het eigen designsysteem en WCAG-contrast; behandel kleurvariaties als testbare hypothese, nooit als regel.', 'cta_rate', ARRAY['visual_treatment']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['knowledge gap','color']::text[], true);
INSERT INTO public.cro_evidence (workspace_id, topic, principle, source_name, source_url, published_at, evidence_level, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, active) VALUES (NULL, 'hero_image_type', 'KNOWLEDGE GAP: geen rigoureus primair onderzoek vergelijkt hero-beeldtypen (foto van persoon vs. illustratie vs. productscreenshot) op conversie.', 'Geen primaire bron gevonden; bestaande claims zijn bureau-case studies', NULL, NULL, 'HYPOTHESIS', 'Aangrenzend bewijs: NN/g toont dat informatief beeld aandacht krijgt en decoratief beeld wordt genegeerd (zie image_relevance) — dat is het enige bruikbare anker.', 'Volledig contextafhankelijk.', 'Kies beeld dat echte informatie draagt (product in gebruik, echte mensen in context) boven decoratief beeld; test type lokaal.', 'cta_rate', ARRAY['hero','media','visual_treatment']::text[], '{}'::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['knowledge gap','hero','imagery']::text[], true);